input.command:
cat > tests/price_test.sh <<'E'
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail
E
bash scripts/verify.sh; echo rc=$?
sed -i 's/\$1 \* 90 + 99/$1 * 90/' bin/price bin/quote lib/invoice.sh
bash scripts/verify.sh; echo rc=$?; grep -rn "99) / 100" . --exclude-dir=.git | wc -l
